<template>
    <div class="car-card" v-if="carData" >
        <div class="car-card__container">

            <div class="car-card__border" >
                
            <div class="car-card__wrapper">

                <NuxtLink :to="`/autopark/${carData.slug}`"  class="car-card__link-wrapper"></NuxtLink>
             
                <ClientOnly>
                    <div class="car-card-slider-wrapper">
                <swiper-container 
                ref="carCardRefSlider" 
    
                class="car-card-slider"
                :pagination="{
                dynamicBullets: false,
                clickable: true
                }"
                >
                    <swiper-slide class="car-card-slider__slide" v-for="item in carData.acf.izobrazheniya_avtomobilya_dlya_kartochki_avto" :key="item">
                        <NuxtLink :to="`/autopark/${carData.slug}`">
                            <!-- <img 
                            :src="item.izobrazhenie.sizes.large" 
                            :alt="item.izobrazhenie.alt"
                             class="car-card-slider__slide-img"> -->

                             <picture class="car-card-slider__slide-img-picture">
                                <source 
                                v-if="item.izobrazhenie?.sizes?.medium_large"
                                media="(max-width: 760px)" 
                                :srcset="item.izobrazhenie.sizes.medium_large">
                                <source 
                                v-if="item.izobrazhenie?.sizes?.large"
                                media="(max-width: 990px)" 
                                :srcset="item.izobrazhenie.sizes.large">
                                <img 
                                :src="item.izobrazhenie.sizes.large" 
                                :alt="item.izobrazhenie.alt" 
                                class="car-card-slider__slide-img"
                                loading="lazy">
                            </picture>

                        </NuxtLink>
                    </swiper-slide>

                </swiper-container>

                    <div class="single-car-swiper-button single-car-swiper-button-prev " @click="swiperCarCard.prev()">
                        <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <path d="M9.29289 18.7071C8.90237 18.3166 8.90237 17.6834 9.29289 17.2929L14.5858 12L9.29289 6.70711C8.90237 6.31658 8.90237 5.68342 9.29289 5.29289C9.68342 4.90237 10.3166 4.90237 10.7071 5.29289L16.7071 11.2929C17.0976 11.6834 17.0976 12.3166 16.7071 12.7071L10.7071 18.7071C10.3166 19.0976 9.68342 19.0976 9.29289 18.7071Z" fill="white"/>
                        </svg>
                    </div>
                    <div class="single-car-swiper-button single-car-swiper-button-next " @click="swiperCarCard.next()">
                        <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <path d="M9.29289 18.7071C8.90237 18.3166 8.90237 17.6834 9.29289 17.2929L14.5858 12L9.29289 6.70711C8.90237 6.31658 8.90237 5.68342 9.29289 5.29289C9.68342 4.90237 10.3166 4.90237 10.7071 5.29289L16.7071 11.2929C17.0976 11.6834 17.0976 12.3166 16.7071 12.7071L10.7071 18.7071C10.3166 19.0976 9.68342 19.0976 9.29289 18.7071Z" fill="white"/>
                        </svg>
                    </div>
                </div>
                </ClientOnly>

                <NuxtLink :to="`/autopark/${carData.slug}`"  class="car-card__data">
                    <div class="car-card__header">
                        <div class="car-card__header-text">
                            <p class="car-card__category" v-if="allCats?.length > 0">{{ getCurrentCategory(carData['categories-cars']) }}</p>
                            <div class="car-card__title" >{{ carData.acf.nazvanie_avto }}</div>
                            
                        </div>
                        <div  class="car-card__header-ar">
                            <svg width="64" height="15" viewBox="0 0 64 15" fill="none" xmlns="http://www.w3.org/2000/svg">
                            <path d="M62.9449 8.17774C63.3414 7.79326 63.3511 7.16017 62.9666 6.7637L56.7011 0.302741C56.3167 -0.0937351 55.6836 -0.10346 55.2871 0.28102C54.8906 0.665501 54.8809 1.29859 55.2654 1.69507L60.8347 7.43814L55.0916 13.0074C54.6951 13.3919 54.6854 14.025 55.0699 14.4215C55.4544 14.818 56.0875 14.8277 56.4839 14.4432L62.9449 8.17774ZM0.015625 6.50391L0.000265975 7.50379L62.2334 8.45974L62.2487 7.45986L62.2641 6.45998L0.030984 5.50402L0.015625 6.50391Z" fill="#F1BD81"/>
                            </svg>

                            <div class="car-card__header-ar-circle"></div>

                        </div>
                    </div>

                    <div class="car-card__body">
                        <div class="car-card__price-row-tab">

                            <template v-if="carData.acf.gibkaya_stoimost_arendy?.length > 0 && carData.acf.gibkaya_stoimost_arendy[0].skidka && carData.acf.gibkaya_stoimost_arendy[0].skidka != ''">
                            <div class="car-card__price-sale-wrapper">
                            <div class="car-card__price-sale-price" >
                                <span class="car-card__price-value"><span v-html="carData.acf.gibkaya_stoimost_arendy[0].skidka"></span>₽</span>
                                / день

                                <div class="car-card__price--sale-price-procent" v-if="carData.acf.gibkaya_stoimost_arendy[0].skidka_v_proczentah">
                                    -{{ carData.acf.gibkaya_stoimost_arendy[0].skidka_v_proczentah }}%
                                </div>
                            </div>

                            <div class="car-card__price-old-price" >
                                <span class="car-card__price-value"><span v-html="carData.acf.gibkaya_stoimost_arendy[0].czena"></span>₽</span>
                                / день
                            </div>
                            </div>

                        </template>

                        <template v-else>
                            <div class="car-card__price" v-if="carData.acf.gibkaya_stoimost_arend?.length > 0" >
                                <span class="car-card__price-value"><span v-html="carData.acf.gibkaya_stoimost_arendy[0].czena"></span>₽</span>
                                / день
                            </div>
                        </template>


                            <!-- <div class="car-card__price" >
                                <span class="car-card__price-value"><span v-html="carData.acf.stoimost_avto_v_sutki"></span>₽</span>
                                / день
                            </div> -->

                            <div class="car-card__header-ar">
                                <svg width="64" height="15" viewBox="0 0 64 15" fill="none" xmlns="http://www.w3.org/2000/svg">
                                <path d="M62.9449 8.17774C63.3414 7.79326 63.3511 7.16017 62.9666 6.7637L56.7011 0.302741C56.3167 -0.0937351 55.6836 -0.10346 55.2871 0.28102C54.8906 0.665501 54.8809 1.29859 55.2654 1.69507L60.8347 7.43814L55.0916 13.0074C54.6951 13.3919 54.6854 14.025 55.0699 14.4215C55.4544 14.818 56.0875 14.8277 56.4839 14.4432L62.9449 8.17774ZM0.015625 6.50391L0.000265975 7.50379L62.2334 8.45974L62.2487 7.45986L62.2641 6.45998L0.030984 5.50402L0.015625 6.50391Z" fill="#F1BD81"/>
                                </svg>

                                <div class="car-card__header-ar-circle"></div>

                            </div>
                        </div>
                        
                        <p class="car-card__description" v-html="truncateString(carData.acf.korotkoe_opisanie, 250)"></p>
                        <div class="car-card__characteristics">

                            <div class="car-card__characteristic">
                                <div class="car-card__characteristic-icon-wrapper">
