<script setup>

//IMPORT
import { ref } from 'vue';


//DATA

const carCardRefSlider = ref(null)

const props = defineProps({
    carData: Object,
    allCats: Array,
})

//recomend gallery
const  swiperCarCard  = useSwiper(carCardRefSlider, {
   loop: false,
   slidesPerView: 1,
   spaceBetween: 0,   
   speed: 600,

   freeMode: false,
   slidesPerView: "auto",
   pagination: true,
  //  centeredSlides: 'auto',
   breakpoints: {
    100: {
      slidesPerView: 1,
      spaceBetween: 0,
    },

    1220: {
       slidesPerView: 1,
      spaceBetween: 30,
    },
  },

})

const getCurrentCategory = (data)=>{
    let currentCutId
    let currentCutTitle

    if(data?.length > 0 ){
        currentCutId = data[0]
        const catElement = props.allCats.find(element => element.id === currentCutId)

        currentCutTitle = catElement.name
    }
    else{
        currentCutTitle = ''
    }

    return currentCutTitle
}

function truncateString(str, maxLength) {
  if (typeof str !== 'string') return ''
  if (str.length <= maxLength) return str
  return str.slice(0, maxLength) + '...'
}

</script>



